using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioVertexMarkerMoveValidation {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 public static void Validate(){var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var primitiveMesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);doc.nodes.Add(new StudioModelDocument.Node{name="Transient Move validation",mesh=primitiveMesh,cutPolygons=polygons,cutTriangles=primitiveMesh.triangles});using(var editor=new StudioModelEditor(()=>{})){editor.Load(doc);editor.SelectObject(0);var type=typeof(StudioModelEditor);type.GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);type.GetField("tool",F).SetValue(editor,Tool.Move);var capture=type.GetMethod("CaptureMoveDrag",F);var field=type.GetField("moveDrag",F);var apply=(Func<Vector3,bool>)type.GetMethod("ApplyMoveDrag",F).CreateDelegate(typeof(Func<Vector3,bool>),editor);var mesh=editor.ActiveMesh;var source=mesh.vertices;var indices=new HashSet<int>(Enumerable.Range(0,source.Length).Where(i=>source[i].x>.1f));editor.Components.UnionWith(indices);type.GetMethod("EnsureComponentDrawing",F).Invoke(editor,null);var transform=editor.Transforms[0];transform.position=new Vector3(2,3,-4);transform.rotation=Quaternion.Euler(21,38,-13);transform.localScale=new Vector3(2,-1.3f,.7f);editor.Document.ReadTransform(0,transform);var center=editor.EditingPivotPosition;var orientation=transform.rotation;var drag=capture.Invoke(editor,new object[]{731,center,orientation,indices,source});field.SetValue(editor,drag);StudioUndo.IncrementCurrentGroup();int group=StudioUndo.GetCurrentGroup();
 foreach(var delta in new[]{new Vector3(.2f,0,0),new Vector3(-.3f,.1f,.07f),Vector3.zero,new Vector3(.03f,-.01f,.2f)}){Check(apply(center+delta),"Changed displacement not applied");var values=mesh.vertices;var markerReadback=new Vector3[values.Length];((GraphicsBuffer)type.GetField("markerPositions",F).GetValue(editor)).GetData(markerReadback);Check(markerReadback.SequenceEqual(values),"Captured Move marker GPU readback differs from mesh");foreach(int i in Enumerable.Range(0,values.Length)){var expected=transform.TransformPoint(source[i])+(indices.Contains(i)?delta:Vector3.zero);Check((transform.TransformPoint(values[i])-expected).sqrMagnitude<1e-10f,"Translated point differs under rotated mirrored nonuniform transform");}int dirty=EditorUtility.GetDirtyCount(mesh);Check(!apply(center+delta)&&EditorUtility.GetDirtyCount(mesh)==dirty,"Unchanged displacement rewrote mesh");if(delta==Vector3.zero)Check(values.SequenceEqual(source),"Returning to origin did not restore exact source positions");}
 var final=mesh.vertices;int version=EditorUtility.GetDirtyCount(mesh);type.GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Object);Check(!apply(center+Vector3.one)&&mesh.vertices.SequenceEqual(final),"Changed component context retained captured translation");type.GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);Check(!apply(new Vector3(float.NaN,0,0))&&!apply(new Vector3(float.PositiveInfinity,0,0))&&mesh.vertices.SequenceEqual(final)&&EditorUtility.GetDirtyCount(mesh)==version,"Invalid target changed mesh");UnityEditor.Undo.FlushUndoRecordObjects();StudioUndo.CollapseUndoOperations(group);StudioUndo.PerformUndo();Check(mesh.vertices.SequenceEqual(source),"One Undo did not restore entire Move gesture");StudioUndo.PerformRedo();Check(mesh.vertices.SequenceEqual(final),"Redo did not restore final Move gesture");Check(type.GetField("moveDrag",F).GetValue(editor)==null,"Undo/Redo retained stale Move capture");
 File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../vertex-marker-move-result.txt")),checks+" assertions PASS: total displacement, exact reversal, mirrored/nonuniform transforms, unselected positions, no-op updates, finite checks and grouped Undo/Redo");}}
 public static void Run(){try{Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../vertex-marker-move-result.txt")),e.ToString());EditorApplication.Exit(1);}}
}
